        'description' => 'Eine einbeinige Übung für den Unterkörper, die Quadrizeps, Gesäß und Beinbeuger trainiert.',
        'instructions' => [
            'Stelle dich aufrecht hin, die Füße hüftbreit.',
            'Mache mit einem Bein einen Schritt nach hinten und senke dich ab, bis beide Knie etwa 90 Grad gebeugt sind.',
            'Halte den Oberkörper aufrecht und den vorderen Fuß flach.',
            'Drücke dich über die vordere Ferse zurück in den Stand.',
            'Wiederhole auf der anderen Seite.',
        ],
        'tips' => [
            'Halte das vordere Knie in Richtung der Zehen.',
            'Mache einen Schritt, der lang genug ist, um im Gleichgewicht zu bleiben.',
            'Lehne dich nicht zu weit nach vorne.',
        ],
    ],
    'reverse-lunge-barbell' => [
        'hash' => '9b9922ac43',
        'description' => 'Eine belastete einbeinige Beinübung, die Quadrizeps, Gesäß und Beinbeuger trainiert.',
        'instructions' => [
            'Lege die Langhantel auf den oberen Rücken und stelle dich aufrecht hin, die Füße hüftbreit.',
