            'Senke dich ab, bis beide Knie etwa 90 Grad gebeugt sind.',
            'Drücke dich über die vordere Ferse zurück in den Stand.',
            'Wiederhole auf der anderen Seite.',
        ],
        'tips' => [
            'Halte die Brust oben und den Oberkörper aufrecht.',
            'Senke dich kontrolliert ab, statt dich fallen zu lassen.',
            'Wähle ein Gewicht, mit dem du sicher das Gleichgewicht hältst.',
        ],
    ],
    'reverse-lunge-dumbbell' => [
        'hash' => '360483281c',
        'description' => 'Eine Ausfallschritt-Variante mit Kurzhanteln, die Quadrizeps, Gesäß und Beinbeuger einbeinig trainiert.',
        'instructions' => [
            'Halte in jeder Hand eine Kurzhantel seitlich am Körper und stelle dich aufrecht hin.',
