    'romanian-deadlift-barbell' => [
        'hash' => 'ef37c74c54',
        'description' => 'Eine Hüftbeuge-Übung mit der Langhantel, die Beinbeuger, Gesäß und unteren Rücken trainiert.',
        'instructions' => [
